"""Owner-approved ordinary outreach caps, independent for each channel."""
CHANNEL_DAILY_LIMITS = {
    'email': 300, 'vk': 50, 'telegram': 50, 'facebook': 50,
}
LIMITS_VERSION = 'outreach-channels-v1'


def sender_daily_limit(channel, policy=None):
    channel = str(channel or '').strip().lower()
    if channel not in CHANNEL_DAILY_LIMITS:
        # This release changes only the four channels explicitly authorized.
        value = (policy or {}).get('daily_limit') or 10
        return max(1, int(value))
    # Unversioned daily_limit=10 was generated by the old generic builder,
    # not an independently reviewed per-channel setting.
    policy = policy or {}
    limit = CHANNEL_DAILY_LIMITS[channel]
    if policy.get('daily_limits_version') == LIMITS_VERSION:
        configured = (policy.get('channel_daily_limits') or {}).get(channel, limit)
        if isinstance(configured, bool) or not isinstance(configured, int) or configured < 1:
            raise ValueError('invalid_outreach_daily_limit')
        limit = min(limit, configured)
    return limit

AUTHOR_CHANNEL_LIMITS = {key: CHANNEL_DAILY_LIMITS[key] for key in ('email','telegram','vk')}
AUTHOR_TOTAL_LIMIT = sum(AUTHOR_CHANNEL_LIMITS.values())
AUTHOR_LIMITS_VERSION = 'localos-author-daily-v3'


def author_limits_match(policy):
    """Preserve previously reviewed v2 identity/content rules; quota is owner-updated."""
    version = policy.get('author_policy_version')
    expected = ({'email':150,'telegram':25,'vk':25} if version == 'localos-author-daily-v2' else
                AUTHOR_CHANNEL_LIMITS if version == AUTHOR_LIMITS_VERSION else None)
    if expected is None:
        return False
    limits = policy.get('channel_daily_limits')
    total = 200 if version == 'localos-author-daily-v2' else AUTHOR_TOTAL_LIMIT
    return (policy.get('daily_limit') == total and isinstance(limits,dict) and limits == expected
            and all(type(value) is int for value in limits.values()))
